use { env, println, Environment, Stdout } from "core:cli";
use fs from "core:fs";
use { Preopens } from "core:fs";
use { Process } from "core:process";
use { Runner, Workspace } from "./src/tools.wado";

export fn run() with (Stdout, Environment, Preopens, Process) {
    let base = "scratchpad/repro-cfg";
    fs::remove_dir_all(base).unwrap();
    fs::create_dir_all(`${base}/.cargo`).unwrap();
    fs::write(`${base}/.cargo/config.toml`, &"[term]\nverbose = false\n").unwrap();
    fs::create_dir_all(`${base}/tree/src`).unwrap();
    fs::write(`${base}/tree/Cargo.toml`, &"[package]\nname = \"t\"\nversion = \"0.1.0\"\nedition = \"2021\"\n").unwrap();
    fs::write(`${base}/tree/src/lib.rs`, &"").unwrap();
    fs::create_dir_all(`${base}/target`).unwrap();
    let home = env("HOME").unwrap();
    let runner = Runner {
        target_dir: `${base}/target`,
        cargo_home: env("CARGO_HOME").unwrap_or(`${home}/.cargo`),
        rustup_home: env("RUSTUP_HOME").unwrap_or(`${home}/.rustup`),
        mise_data_dir: "",
        programs: ["cargo", "sh"],
    };
    let ws = Workspace { root: `${base}/tree`, runner: Some(runner) };
    let ran = ws.run_command(&["cargo", "metadata", "--offline", "--no-deps", "--format-version", "1"], 120).unwrap();
    println(`cargo metadata succeeded=${ran.succeeded}\n${ran.report}`);
    let ran2 = ws.run_command(&["sh", "-c", "ls -la .. ; cat ../.cargo/config.toml"], 20).unwrap();
    println(`sh: ${ran2.report}`);
}

import { execFileSync, spawnSync } from "node:child_process";
import os from "node:os";
import fs from "node:fs";
const home = os.homedir();
const cargoHome = process.env.CARGO_HOME || `${home}/.cargo`;
const rustupHome = process.env.RUSTUP_HOME || `${home}/.rustup`;
const args = ["run", "--bin", "wado", "--", "run"];
for (const p of [cargoHome, rustupHome]) if (fs.existsSync(p)) args.push("--process-read", p);
args.push("package-eddy/repro_cargo_config.wado");
console.log(args.join(" "));
const r = spawnSync("cargo", args, { encoding: "utf8", env: { ...process.env, PATH: "/usr/bin:" + process.env.PATH } , maxBuffer: 1 << 28});
console.log("status", r.status);
console.log(r.stdout);
console.log(r.stderr.slice(-4000));
